'use strict';
// In-memory demonstration only. No server calls, persistent credentials or real uploads.
// Scope A baseline: existing capabilities only; search/filter/rename/manual-theme are
// exploration-only and intentionally absent from this baseline (see BASELINE.md).
const $ = s => document.querySelector(s);
const icon = n => `<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const btn = (action,label,ico='',cls='action-button',extra='') => `<button class="${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const ib = (action,label,ico,extra='') => `<button class="icon-button" data-action="${action}" aria-label="${label}" title="${label}" ${extra}>${icon(ico)}</button>`;
const badge = (text,cls='') => `<span class="pill ${cls}">${text}</span>`;
const fileConflictOptions=[['resume_or_overwrite','续传，完整则跳过'],['overwrite','覆盖'],['skip_existing','跳过'],['rename','自动改名'],['fail','报错停止']];
const folderConflictOptions=[['merge','合并'],['rename','自动改名'],['skip','跳过'],['fail','报错停止']];
const conflictLabel=(code,list)=>(list.find(o=>o[0]===code)||['','—'])[1];
let state,pendingLeave;
function initial(){return {page:'home',path:[],grid:false,taskTab:'活跃',taskId:1,connectionId:null,editConnection:null,connectionSource:'home',editPreset:null,presetsSource:'home',mediaId:10,loading:false,loadError:false,tasksLoadError:false,mediaError:false,selectionMode:false,selectedTaskIds:[],formDirty:false,uploadDraft:null,presetLocal:null,connections:[{id:1,name:'家庭 NAS',url:'https://nas.home.example/dav',user:'han',dir:'/共享文件',selfSigned:false},{id:2,name:'工作空间',url:'https://studio.example/webdav',user:'studio',dir:'/项目文件',selfSigned:false}],tasks:[{id:1,name:'夏日山野 · 照片备份',status:'running',pct:68,total:'2.40 GB',done:'1.63 GB',count:'86 / 128',target:'/照片/2026 夏日山野',policy:'resume_or_overwrite',connection:'家庭 NAS',warnings:[]},{id:2,name:'工作资料归档',status:'paused',pct:32,total:'840 MB',done:'269 MB',count:'12 / 38',target:'/文档/项目归档',policy:'resume_or_overwrite',connection:'工作空间',warnings:[]},{id:3,name:'相机胶卷 · 九月',status:'completed',pct:100,total:'1.18 GB',done:'1.18 GB',count:'64 / 64',target:'/照片/相机胶卷',policy:'resume_or_overwrite',connection:'家庭 NAS',warnings:['跳过 2 个同名文件：远端已存在且大小一致']},{id:4,name:'旅途视频',status:'failed',pct:43,total:'4.20 GB',done:'1.81 GB',count:'3 / 7',target:'/视频/旅途',policy:'resume_or_overwrite',connection:'家庭 NAS',warnings:['1 个文件被文件名过滤规则跳过']},{id:5,name:'相机文件夹 · 增量备份',status:'running',pct:null,total:null,done:'512 MB',count:'12 个文件',target:'/照片/相机胶卷',policy:'resume_or_overwrite',connection:'家庭 NAS',warnings:[]}],presets:[{id:1,name:'手机照片备份',sourceType:'folder',source:'相机 · 12 个文件',target:'/照片/相机胶卷',connection:'家庭 NAS',policy:'resume_or_overwrite',folderPolicy:'merge'},{id:2,name:'工作资料归档',sourceType:'file',source:'项目归档.zip',target:'/文档/项目归档',connection:'工作空间',policy:'skip_existing'}],files:[{id:10,name:'山野之间.jpg',type:'图片',size:'8.4 MB',date:'今天 09:32',image:'assets/mountain.jpg',folder:'照片'},{id:11,name:'森林来信.jpg',type:'图片',size:'6.2 MB',date:'今天 09:30',image:'assets/forest.jpg',folder:'照片'},{id:15,name:'晨雾中的山脊线.jpg',type:'图片',size:'7.1 MB',date:'昨天 07:58',image:'assets/mountain.jpg',folder:'照片/2026 夏日山野'},{id:12,name:'山间的清晨.mp4',type:'视频',size:'248 MB',date:'昨天 18:26',folder:'视频'},{id:13,name:'旅行计划.pdf',type:'文档',size:'1.2 MB',date:'09 月 28 日',folder:'文档'},{id:16,name:'2026-夏季北疆环线旅行拍摄原始素材汇总目录清单最终版.pdf',type:'文档',size:'3.8 MB',date:'09 月 27 日',folder:'文档'},{id:14,name:'周末歌单.flac',type:'音频',size:'32 MB',date:'09 月 27 日',folder:'音乐'},{id:17,name:'使用说明.txt',type:'文档',size:'2 KB',date:'09 月 26 日',folder:''}],folders:['照片','照片/2026 夏日山野','视频','文档','音乐'],notifications:true,battery:false};}
state=initial();
const pages=[['home','连接首页'],['browser','文件浏览'],['tasks','任务中心'],['presets','上传预设'],['connection','连接编辑'],['settings','设置']];
const notes={home:['01','少一点界面，<br>多一点文件。','连接卡片只保留目的地、地址与主要操作。传输状态独立出现，不再淹没在连接列表里。'],browser:['02','文件先行，<br>操作随行。','文件夹与文件分层展示，多层目录用面包屑返回。列表与网格切换保留，文件行使用类型图标。'],connectionSelect:['02','先选目的地，<br>再看文件。','文件入口不默认进入某一台 NAS。显式选择后，本次会话内的目录位置会被记住；连接被删除时回到这里重新选择。'],tasks:['03','每一种状态，<br>都说清楚。','传输、暂停、等待、失败各有明确标签。支持多选与批量删除；跳过与过滤产生警告，不会静默消失。'],detail:['03','进度有分寸，<br>问题有出口。','大进度环只出现在任务详情。总量未知时显示不定进度；失败给出原因和重试入口，取消始终经过二次确认。'],presets:['04','重复的事情，<br>少做一次。','把来源、目的地和冲突策略组合成一个预设。一键运行前，仍然允许你确认这次上传。'],connection:['05','连接设置，<br>不必猜测。','标签在输入框上方，帮助信息紧邻字段。测试连接与保存分开；有未保存修改时返回会先提醒。'],settings:['06','不打扰，<br>但有交代。','权限用实际用途解释。这个原型不会请求系统权限，也不会真的写入设备；主题跟随系统。'],media:['02','把空间，<br>还给内容。','图片预览减少界面干扰，保留前后切换与文件信息。视频可选本地文件演示，不访问远端 NAS。'],presetEdit:['04','常用规则，<br>一次设置。','来源类型、本地选择、冲突策略与移动上传形成完整的上传意图。高级选项折叠，避免第一次使用就面对所有参数。']};
const statusMap={running:['传输中','blue'],paused:['已暂停','warn'],completed:['已完成',''],failed:['失败','danger'],waiting:['等待中','neutral'],cancelled:['已取消','neutral']};
function statusBadge(t){return badge(...statusMap[t.status]);}
function navigate(page){state.page=page;state.loading=false;state.loadError=false;if(['connection','presetEdit'].includes(page))state.formDirty=false;if(page==='presetEdit')state.presetLocal=null;render();$('#content').scrollTop=0;}
function header(title,sub,actions='',back=false){$('#appHeader').innerHTML=`${back?ib('back','返回','arrow-left'):''}<div class="header-title">${sub?`<div class="eyeline">${sub}</div>`:''}<h2>${title}</h2></div><div class="header-actions">${actions}</div>`;}
function render(){
 const navPage=state.page==='connectionSelect'?'browser':state.page==='detail'?'tasks':state.page;
 const mainTabs=['home','browser','tasks','settings'];
 const showNav=mainTabs.includes(navPage)&&!(navPage==='tasks'&&state.selectionMode);
 const nav=$('#bottomNav');nav.classList.toggle('hidden',!showNav);
 nav.innerHTML=showNav?[['home','连接','server'],['browser','文件','folder'],['tasks','传输','cloud-upload'],['settings','设置','settings']].map(([p,n,i])=>`<button data-page="${p}" class="${navPage===p?'active':''}" ${navPage===p?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span>${n}</button>`).join(''):'';
 $('#chapterNav').innerHTML=pages.map(([p,n],i)=>`<button data-page="${p}" class="${navPage===p?'active':''}"><span>0${i+1}</span>${n}</button>`).join('');
 const note=notes[state.page]||notes.home;$('.note-number').textContent=note[0];$('#noteTitle').innerHTML=note[1];$('#noteBody').textContent=note[2];$('#pageCaption').textContent=pages.find(p=>p[0]===state.page)?.[1]||({detail:'任务详情',media:'媒体预览',presetEdit:'预设编辑',connectionSelect:'选择连接'}[state.page]);
 const views={home:homeView,browser:browserView,connectionSelect:connectionSelectView,tasks:tasksView,detail:detailView,connection:connectionView,presets:presetsView,presetEdit:presetEditView,settings:settingsView,media:mediaView};
 $('#content').innerHTML=views[state.page]();
}
function progressHtml(t,light){if(t.pct==null)return `<div class="progress indeterminate${light?' light':''}"><span></span></div>`;return `<div class="progress"><span style="width:${t.pct}%"></span></div>`;}
function taskNumbers(t){return t.pct==null?`<span>${t.done} 已上传</span><span>总计大小未知</span>`:`<span>${t.done} / ${t.total}</span><span>${t.pct}%</span>`;}
function warningLines(w){return (w||[]).map(x=>`<div class="warning-line">${icon('alert-triangle')}<span>${esc(x)}</span></div>`).join('');}
function homeView(){header('NasTools','你的私人文件空间',ib('new-connection','新建连接','plus'));
 const active=state.tasks.filter(t=>['running','waiting'].includes(t.status));const t=active[0];
 return `<div class="welcome"><h1>一切，都在这里。</h1><p>连接你的 NAS，随时接着上一次。</p></div>${t?`<button class="transfer-banner" data-action="detail" data-id="${t.id}"><div class="row"><span class="kicker">${active.length} 个任务进行中</span>${icon('arrow-up-right')}</div><h3>${esc(t.name)}</h3>${progressHtml(t,true)}<div class="row between meta"><span>${t.pct==null?t.done+' 已上传 · 总计未知':t.done+' / '+t.total}</span><span>${t.pct==null?'—':t.pct+'%'}</span></div></button>`:`<div class="shortcut">${icon('circle-check')}<div><strong>暂时没有进行中的传输</strong><p class="meta">文件准备好了，就从浏览页开始上传。</p></div></div>`}
 <div class="section-head"><h3>我的连接 <small>${state.connections.length}</small></h3><span class="meta">WebDAV</span></div>${state.connections.length?state.connections.map(c=>`<article class="connection"><div class="row"><div class="icon-bubble">${icon('server')}</div><div class="grow"><h3>${esc(c.name)}</h3><p class="meta">${esc(new URL(c.url).host)}</p></div>${ib('connection-menu','管理连接','dots',`data-id="${c.id}"`)}</div><div class="connection-footer"><span>${icon('lock')} 已配置认证</span>${btn('browse','浏览文件','arrow-right','',`data-id="${c.id}"`)}</div></article>`).join(''):empty('还没有连接','添加一个 WebDAV 地址，开始管理你的文件。','new-connection','新建连接')}
 <div class="section-head"><h3>常用工作流</h3></div><button class="shortcut" data-page="presets" data-source="home"><div class="icon-bubble small">${icon('bookmark')}</div><div class="grow"><strong>上传预设</strong><p class="meta">照片备份、工作归档，一次设置</p></div>${icon('chevron-right')}</button><p class="tiny-note">设计演示 · 连接与传输数据均为模拟</p>`;
}
function empty(title,text,action='',label=''){return `<div class="empty">${icon('folder')}<h3>${title}</h3><p>${text}</p>${action?btn(action,label):''}</div>`;}
function connectionSelectView(){header('选择连接','文件空间','',true);
 if(!state.connections.length)return empty('还没有连接','先新建一个 WebDAV 连接，才能浏览文件。','new-connection','新建连接');
 return `<p class="form-intro">选择要浏览的 NAS。本次会话内会记住你的选择和目录位置。</p>${state.connections.map(c=>`<button class="connection full" data-action="pick-connection" data-id="${c.id}" style="text-align:left"><div class="row"><div class="icon-bubble">${icon('server')}</div><div class="grow"><h3>${esc(c.name)}</h3><p class="meta">${esc(new URL(c.url).host)}</p></div>${icon('chevron-right')}</div></button>`).join('')}<div class="upload-bar">${btn('new-connection','新建连接','plus','action-button secondary full')}</div>`;
}
function browserView(){const c=state.connections.find(c=>c.id===state.connectionId);
 if(!c)return connectionSelectView();
 header(esc(c.name),'文件空间',ib('switch-connection','切换连接','arrows-exchange')+ib('browser-menu','文件操作','plus'),false);
 return `<div class="row between"><div class="crumbs"><button data-action="crumb" data-index="0">共享文件</button>${state.path.map((seg,i)=>`${icon('chevron-right')}<button data-action="crumb" data-index="${i+1}">${esc(seg)}</button>`).join('')}</div>${ib('view','切换列表或网格',state.grid?'list':'layout-grid')}</div><div id="fileArea">${fileArea()}</div><div class="upload-bar">${btn('upload','上传到当前目录','upload','action-button full')}</div><p class="tiny-note">搜索与类型筛选属于后续规划，未包含在本轮范围。</p>`;
}
function fileArea(){if(state.loading)return '<div role="status" aria-label="正在加载"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div>';if(state.loadError)return `<div class="inline-message error">无法加载目录。这是用于预览的模拟网络错误。</div>${btn('retry-load','重新加载','refresh','action-button secondary full')}`;
 const prefix=state.path.length?state.path.join('/')+'/':'';
 const here=state.path.join('/');
 const folders=state.folders.filter(f=>f.startsWith(prefix)&&!f.slice(prefix.length).includes('/')).map(f=>f.slice(prefix.length));
 const files=state.files.filter(f=>f.folder===here);
 if(!files.length&&!folders.length)return empty('这个目录是空的','上传文件，或者返回上一级看看。');
 return `${folders.length?`<div class="folder-grid">${folders.map(f=>`<button class="folder-card" data-action="folder" data-folder="${esc(prefix+f)}">${icon('folder')}<strong>${esc(f)}</strong><p class="meta">${state.files.filter(x=>x.folder===prefix+f).length} 个文件 · ${state.folders.filter(x=>x.startsWith(prefix+f+'/')).length} 个子目录</p></button>`).join('')}</div>`:''}<div class="row between meta"><span>${state.path.length?'目录内容':'最近的文件'}</span><span>${files.length} 个文件</span></div><div class="file-list ${state.grid?'grid':''}">${files.map(f=>`<div class="file-row"><button class="file-main" data-action="open-file" data-id="${f.id}"><span class="icon-bubble">${icon(f.type==='图片'?'photo':f.type==='视频'?'video':f.type==='音频'?'music':'file-text')}</span><span class="grow"><strong>${esc(f.name)}</strong><span class="meta">${f.size} · ${f.date}</span></span></button>${ib('file-menu','管理 '+esc(f.name),'dots',`data-id="${f.id}"`)}</div>`).join('')}</div>`;
}
function tasksView(){
 if(state.selectionMode){const n=state.selectedTaskIds.length;header(`已选 ${n} 项`,'批量管理',`<button class="text-button" data-action="select-all">全选</button><button class="text-button" data-action="exit-selection">完成</button>`);}
 else header('任务中心','文件正在抵达目的地',`<button class="text-button" data-action="enter-selection">多选</button>${ib('upload','新建上传','plus')}`);
 if(state.tasksLoadError)return `<div class="inline-message error">无法加载任务列表。这是用于预览的模拟错误。</div>${btn('retry-tasks','重新加载','refresh','action-button secondary full')}`;
 const all=state.tasks.filter(t=>state.taskTab==='活跃'?['running','paused','waiting'].includes(t.status):state.taskTab==='已完成'?t.status==='completed':['failed','cancelled'].includes(t.status));
 return `<div class="tabbar" role="tablist">${['活跃','已完成','失败'].map(t=>`<button role="tab" aria-selected="${state.taskTab===t}" class="${state.taskTab===t?'active':''}" data-action="task-tab" data-tab="${t}">${t}</button>`).join('')}</div><div class="section-head"><h3>${all.length} 个任务</h3><button class="demo-link" data-action="simulate-tasks-error">演示：加载失败</button></div>${all.length?all.map(taskCard).join(''):empty('暂无'+state.taskTab+'任务','新的传输任务会出现在这里。','upload','新建上传')}${state.selectionMode?`<div class="select-bar">${btn('batch-delete',`删除所选（${state.selectedTaskIds.length}）`,'trash','action-button danger full',state.selectedTaskIds.length?'':'disabled')}</div>`:''}<div class="tiny-note">状态不会自动跳动，便于比较设计。同名跳过与过滤跳过会以警告呈现，不再静默。</div>`;}
function taskCard(t){const selected=state.selectedTaskIds.includes(t.id);
 if(state.selectionMode)return `<button class="task-card full task-open ${selected?'selected':''}" data-action="toggle-select" data-id="${t.id}" aria-pressed="${selected}"><div class="row between"><div class="icon-bubble small">${icon(selected?'check':'cloud-upload')}</div>${statusBadge(t)}</div><h3 class="task-title" style="margin-top:15px">${esc(t.name)}</h3><p class="meta">${esc(t.connection)} · ${esc(t.target)}</p>${progressHtml(t)}<div class="task-numbers">${taskNumbers(t)}</div>${warningLines(t.warnings)}</button>`;
 return `<article class="task-card"><button class="task-open" data-action="detail" data-id="${t.id}"><div class="row between"><div class="icon-bubble small">${icon(t.status==='completed'?'circle-check':'cloud-upload')}</div>${statusBadge(t)}</div><h3 class="task-title" style="margin-top:15px">${esc(t.name)}</h3><p class="meta">${esc(t.connection)} · ${esc(t.target)}</p>${progressHtml(t)}<div class="task-numbers">${taskNumbers(t)}</div>${warningLines(t.warnings)}</button><div class="task-controls"><span class="meta">${t.status==='running'?'12.8 MB/s · 预计剩余 1 分钟':t.status==='failed'?'连接中断 · 点击重试':t.status==='paused'?'暂停中，进度已保留':t.status==='completed'?'所有文件已完成':'等待操作'}</span>${t.status==='running'?ib('pause','暂停','player-pause',`data-id="${t.id}"`):['paused','waiting'].includes(t.status)?ib('resume','恢复','player-play',`data-id="${t.id}"`):t.status==='failed'?ib('retry','重试','refresh',`data-id="${t.id}"`):ib('detail','查看详情','chevron-right',`data-id="${t.id}"`)}</div></article>`;}
function detailView(){const t=state.tasks.find(t=>t.id===state.taskId);if(!t){state.page='tasks';return tasksView();}header('任务详情','传输 / '+esc(t.connection),'',true);return `<div class="detail-top">${statusBadge(t)}<div class="ring" style="--angle:${t.pct==null?0:t.pct*3.6}deg"><div class="ring-inner">${t.pct==null?'<strong>—</strong><small>进度未知</small>':`<strong>${t.pct}<small>%</small></strong><small>${t.done} / ${t.total}</small>`}</div></div><h3>${esc(t.name)}</h3><p class="meta">${t.count}${t.pct==null?' · 总计大小未知':''}</p></div>${t.status==='failed'?'<div class="inline-message error">WebDAV 连接中断，未能继续上传。请检查网络后重试。已传数据会按冲突策略处理。</div>':''}${warningLines(t.warnings)}<div class="detail-stats"><div><strong>${t.status==='running'?'12.8':'—'} <small>MB/s</small></strong><small>当前速度</small></div><div><strong>${t.status==='running'?'01:02':'—'}</strong><small>预计剩余</small></div></div><div class="info-row"><span>远端目录</span><span>${esc(t.target)}</span></div><div class="info-row"><span>同名文件</span><span>${esc(t.policy?conflictLabel(t.policy,fileConflictOptions):'续传或覆盖')}</span></div><div class="info-row"><span>上传方式</span><span>复制上传</span></div><div class="form-actions">${t.status==='running'?btn('pause','暂停传输','player-pause','action-button',`data-id="${t.id}"`):['paused','waiting'].includes(t.status)?btn('resume','恢复传输','player-play','action-button',`data-id="${t.id}"`):t.status==='failed'?btn('retry','重试上传','refresh','action-button',`data-id="${t.id}"`):''}${btn(['completed','cancelled','failed'].includes(t.status)?'delete-task':'cancel-task',['completed','cancelled','failed'].includes(t.status)?'删除记录':'取消任务','','action-button secondary',`data-id="${t.id}"`)}</div><div class="section-head"><h3>文件明细</h3><span class="meta">示例条目</span></div><div class="file-row">${icon('circle-check')}<div><h3 class="task-title">山野之间.jpg</h3><p class="meta">8.4 MB · 已上传</p></div></div><div class="file-row">${icon('photo')}<div><h3 class="task-title">森林来信.jpg</h3><p class="meta">6.2 MB · ${t.status==='completed'?'已上传':'等待上传'}</p></div></div>`;}
function field(name,label,value='',type='text',help=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${['name','url','target','remoteRoot'].includes(name)?'required':''}>${help?`<small>${help}</small>`:''}</label>`;}
function selectField(name,label,options,current){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${current===v?'selected':''}>${t}</option>`).join('')}</select></label>`;}
function connectionView(){const c=state.connections.find(c=>c.id===state.editConnection);header(c?'编辑连接':'新建连接','WebDAV 连接','',true);return `<p class="form-intro">一个地址，就能找到你的文件。<br>支持家庭 NAS、自建服务与 WebDAV 网盘。</p><form id="connectionForm" autocomplete="off">${field('name','连接名称',c?.name||'')}${field('url','WebDAV 地址',c?.url||'','url','例如 https://nas.example.com/dav')}${field('user','用户名',c?.user||'')}${field('password','密码','','password','原型不保存密码。这里可留空，使用模拟认证。')}${field('dir','默认远端目录',c?.dir||'/')}<label class="check-row"><span>信任自签名证书<small class="muted" style="display:block">仅在你确认服务器可信时开启</small></span><input type="checkbox" name="selfSigned" ${c?.selfSigned?'checked':''}></label><div id="connectionResult" role="status"></div><div class="form-actions">${btn('test-connection','模拟测试','','action-button secondary','type="button"')}<button type="submit" class="action-button">保存连接</button></div><p class="tiny-note">测试不会发起网络请求。连接仅保留在当前页面内存中，刷新后重置。</p></form>`;}
function presetsView(){header('上传预设','把常用操作，变成一个动作',ib('new-preset','新建预设','plus'),true);return `<p class="form-intro">来源、目标和冲突策略，提前安排好。<br>下次上传，就不用再填一遍。</p>${state.presets.length?state.presets.map(p=>`<article class="preset"><div class="preset-header"><div class="icon-bubble">${icon('bookmark')}</div><div class="grow"><h3>${esc(p.name)}</h3><p class="meta">${esc(p.connection)} · ${p.sourceType==='folder'?'文件夹':'文件'}</p></div>${ib('preset-menu','管理预设','dots',`data-id="${p.id}"`)}</div><div class="preset-path"><div>${icon('folder')}${esc(p.source)}</div><div>${icon('arrow-right')}${esc(p.target)}</div></div><div class="row between" style="margin-top:12px"><span class="meta">${conflictLabel(p.policy,fileConflictOptions)}${p.folderPolicy?' · 文件夹'+conflictLabel(p.folderPolicy,folderConflictOptions):''}</span>${btn('run-preset','运行预设','player-play','text-button',`data-id="${p.id}"`)}</div></article>`).join(''):empty('还没有上传预设','把常用的照片备份或文件归档保存下来。','new-preset','新建预设')}`;}
function presetEditView(){const p=state.presets.find(p=>p.id===state.editPreset);const local=state.presetLocal||{type:p?.sourceType||'folder',label:p?.source||''};header(p?'编辑预设':'新建预设','上传工作流','',true);
 return `<form id="presetForm"><span class="field"><span>来源类型</span><div class="choice-row"><button type="button" class="choice ${local.type==='file'?'active':''}" data-action="preset-source" data-kind="file">${icon('file-text')}文件</button><button type="button" class="choice ${local.type==='folder'?'active':''}" data-action="preset-source" data-kind="folder">${icon('folders')}文件夹</button></div></span><div class="upload-choice" style="margin-bottom:6px">${icon('cloud-upload')}${local.label?`已选择：${esc(local.label)}`:'尚未选择本地来源'}<p class="meta">正式应用通过系统文件选择器授权，原型仅模拟。</p></div>${btn('pick-local','选择本地'+(local.type==='folder'?'文件夹':'文件'),'folder','action-button secondary full')}
 ${field('name','预设名称',p?.name||'')}<label class="field"><span>目标连接</span><select name="connection">${state.connections.map(c=>`<option ${p?.connection===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${field('remoteRoot','远端目录',p?.target||'/备份')}
 ${selectField('policy','同名文件',fileConflictOptions,p?.policy||'resume_or_overwrite')}${local.type==='folder'?selectField('folderPolicy','同名文件夹',folderConflictOptions,p?.folderPolicy||'merge'):''}
 <label class="check-row"><span>仅 Wi-Fi 上传<small class="muted" style="display:block">移动网络下暂停，回到 Wi-Fi 继续</small></span><input type="checkbox" name="wifiOnly" ${p?.wifiOnly!==false?'checked':''}></label><label class="check-row"><span>移动上传<small class="muted" style="display:block">上传完成后删除本地${local.type==='folder'?'文件夹':'文件'}</small></span><input type="checkbox" name="deleteAfterUpload" ${p?.deleteAfterUpload?'checked':''}></label>
 <details><summary class="meta">高级选项</summary>${field('chunk','分块大小 MB',p?.chunk||'10','number')}${field('regex','文件名过滤正则',p?.regex||'')}</details><button class="action-button full" type="submit" style="margin-top:24px" ${!state.connections.length?'disabled':''}>保存预设</button>${!state.connections.length?'<p class="tiny-note">请先新建一个连接。</p>':''}</form>`;}
function settingsView(){header('设置','按自己的习惯使用');return `<div class="settings-brand"><span class="brand-mark">n.</span><div><h2>NasTools</h2><p class="meta">你的私人文件空间</p></div></div><div class="section-head"><h3>工作流</h3></div><div class="settings-group"><button class="setting-row" data-page="presets" data-source="settings">${icon('bookmark')}<span class="grow"><strong>上传预设</strong><span class="meta" style="display:block">管理常用来源与上传规则</span></span>${icon('chevron-right')}</button></div><div class="section-head"><h3>后台传输</h3></div><div class="settings-group"><button class="setting-row" data-action="permission" data-kind="notifications">${icon('bell')}<span class="grow"><strong>通知权限</strong><span class="meta" style="display:block">显示后台上传进度</span></span>${badge(state.notifications?'已允许':'未允许',state.notifications?'':'warn')}</button><button class="setting-row" data-action="permission" data-kind="battery">${icon('battery-3')}<span class="grow"><strong>电池优化</strong><span class="meta" style="display:block">避免后台任务被系统中断</span></span>${badge(state.battery?'不受限制':'待设置',state.battery?'':'warn')}</button></div><div class="section-head"><h3>关于此设计</h3></div><p class="form-intro">范围 A 基准原型 / Concept 01 v1.1<br>主题跟随系统；搜索、筛选、重命名等属于后续规划。<br>此版本不代表已实现的 Android 功能。</p>`;}
function mediaView(){const f=state.files.find(f=>f.id===state.mediaId);if(!f){state.page='browser';return browserView();}header(esc(f.name),'共享文件 / '+f.type,'',true);const media=state.files.filter(x=>x.type==='图片'||x.type==='视频');
 const frame=state.mediaError?`<div class="media-frame"><div class="empty" style="color:#ced9cf">${icon('alert-circle')}<h3 style="color:#edf1e9">无法加载媒体</h3><p>模拟网络或解码失败。</p>`+btn('retry-media','重新加载','refresh','action-button secondary')+`</div></div>`:f.image?`<div class="media-frame"><img src="${f.image}" alt="${esc(f.name)}"></div>`:`<div class="media-frame"><div class="empty" style="color:#ced9cf">${icon('video')}<h3 style="color:#edf1e9">视频预览</h3><p>这是一个演示视频条目。<br>选择本地视频，体验播放器效果。</p><label class="action-button">选择本地视频<input type="file" id="localVideo" accept="video/*" hidden></label></div></div>`;
 return `${frame}<div class="media-actions">${btn('prev-media','上一项','arrow-left','text-button')}${badge((media.findIndex(x=>x.id===f.id)+1)+' / '+media.length,'neutral')}${btn('next-media','下一项','arrow-right','text-button')}</div><div class="row" style="justify-content:center"><button class="demo-link" data-action="simulate-media-error">演示：加载失败</button></div><div class="section-head"><h3>文件信息</h3></div><div class="info-row"><span>大小</span><span>${f.size}</span></div><div class="info-row"><span>类型</span><span>${f.type}</span></div><div class="info-row"><span>修改时间</span><span>${f.date}</span></div><p class="tiny-note">图片为本地演示素材，非 NAS 实时内容。<br>选择的视频只在本机播放，不会上传。</p>`;}
let toastTimer,returnFocus,videoUrl;
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function sheet(title,body){returnFocus=document.activeElement;$('#sheetTitle').textContent=title;$('#sheetBody').innerHTML=body;if(!$('#sheet').open)$('#sheet').showModal();}
function closeSheet(){$('#sheet').close();if(returnFocus?.isConnected)returnFocus.focus();}
function confirmAction(title,message,action,id,label='确认'){sheet(title,`<p class="form-intro">${esc(message)}</p><div class="form-actions">${btn('close','取消','','action-button secondary')}${btn(action,label,'','action-button danger',`data-id="${id}"`)}</div>`);}
function requestLeave(target){if(!state.formDirty){navigate(target);return;}pendingLeave=target;sheet('未保存的修改',`<p class="form-intro">未保存的修改将会丢失。确定要离开吗？</p><div class="form-actions">${btn('close','继续编辑','','action-button secondary')}${btn('leave','离开','','action-button danger')}</div>`);}
function uploadSheet(preset){if(!state.connections.length){navigate('home');toast('请先新建连接');return;}
 const d=state.uploadDraft&&state.uploadDraft.fromPreset===!!preset?state.uploadDraft:{fromPreset:!!preset,sourceType:preset?.sourceType||null,label:preset?.source||'',target:preset?.target||'/'+(state.path.join('/')||'共享文件'),connection:preset?.connection||state.connections[0].name,policy:preset?.policy||'resume_or_overwrite',folderPolicy:preset?.folderPolicy||'merge',moveAfter:false,savePreset:false,presetName:preset?.name||''};
 state.uploadDraft=d;
 sheet('新建上传',`<form id="uploadForm"><span class="field"><span>来源</span><div class="choice-row"><button type="button" class="choice ${d.sourceType==='file'?'active':''}" data-action="pick-source" data-kind="file">${icon('file-text')}选择文件</button><button type="button" class="choice ${d.sourceType==='folder'?'active':''}" data-action="pick-source" data-kind="folder">${icon('folders')}选择文件夹</button></div></span>${d.label?`<p class="meta" style="margin:0 2px 12px">已选择：${esc(d.label)}</p>`:'<p class="meta" style="margin:0 2px 12px">正式应用通过系统选择器授权；原型使用示例文件，不会读取本地内容。</p>'}
 ${field('target','远端目录',d.target)}<label class="field"><span>目标连接</span><select name="connection">${state.connections.map(c=>`<option ${d.connection===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>
 ${selectField('policy','同名文件',fileConflictOptions,d.policy)}${d.sourceType==='folder'?selectField('folderPolicy','同名文件夹',folderConflictOptions,d.folderPolicy):''}
 <label class="check-row"><span>移动上传<small class="muted" style="display:block">上传完成后删除本地${d.sourceType==='folder'?'文件夹':'文件'}</small></span><input type="checkbox" name="moveAfter" ${d.moveAfter?'checked':''}></label>
 <label class="check-row"><span>保存为预设<small class="muted" style="display:block">把这次的选择保存下来，下次直接运行</small></span><input type="checkbox" name="savePreset" ${d.savePreset?'checked':''}></label>
 ${d.savePreset?field('presetName','预设名称',d.presetName):''}
 <p class="tiny-note">同名文件的默认策略按远端大小判断：一致则跳过，不完整则续传。</p><button type="submit" class="action-button full" style="margin-top:18px" ${d.sourceType?'':'disabled'}>开始上传</button></form>`);}
const actions={
 'new-connection':()=>{state.connectionSource=state.page==='connectionSelect'?'connectionSelect':'home';state.editConnection=null;navigate('connection');},
 'browse':el=>{state.connectionId=+el.dataset.id;state.path=[];navigate('browser');},
 'pick-connection':el=>{state.connectionId=+el.dataset.id;state.path=[];navigate('browser');},
 'switch-connection':()=>navigate('connectionSelect'),
 'connection-menu':el=>sheet('管理连接',`${btn('edit-connection','编辑连接','pencil','menu-item',`data-id="${el.dataset.id}"`)}${btn('delete-connection','删除连接','trash','menu-item danger',`data-id="${el.dataset.id}"`)}`),
 'edit-connection':el=>{state.connectionSource='home';state.editConnection=+el.dataset.id;closeSheet();navigate('connection');},
 'delete-connection':el=>confirmAction('删除连接','将同时删除此连接相关的上传预设。NAS 上的文件不受影响，此操作不可撤销。','confirm-delete-connection',el.dataset.id,'删除连接'),
 'confirm-delete-connection':el=>{const id=+el.dataset.id;state.connections=state.connections.filter(c=>c.id!==id);if(state.connectionId===id)state.connectionId=null;state.formDirty=false;closeSheet();navigate(state.connectionSource||'home');toast('演示连接已删除，相关预设一并移除');},
 'back':()=>{const map={connection:state.connectionSource||'home',presets:state.presetsSource,presetEdit:'presets',detail:'tasks',media:'browser',connectionSelect:'home'};const target=map[state.page]||'home';if(['connection','presetEdit'].includes(state.page))requestLeave(target);else navigate(target);},
 'leave':()=>{state.formDirty=false;closeSheet();navigate(pendingLeave);},
 'theme':()=>toggleTheme(), 'close':()=>closeSheet(),
 'crumb':el=>{state.path=state.path.slice(0,+el.dataset.index);render();},
 'folder':el=>{state.path=el.dataset.folder.split('/');render();},'view':()=>{state.grid=!state.grid;render();},
 'refresh':()=>{state.loadError=false;state.loading=true;render();setTimeout(()=>{state.loading=false;if(state.page==='browser')render();toast('演示目录已刷新');},650);},
 'retry-load':()=>{state.loadError=false;render();},
 'browser-menu':()=>sheet('文件操作',btn('upload','上传示例文件','upload','menu-item')+btn('new-folder','新建文件夹','folder','menu-item')+btn('simulate-first-error','演示：首次加载失败','alert-circle','menu-item')+btn('simulate-refresh-error','演示：刷新失败（保留列表）','alert-circle','menu-item')),
 'simulate-first-error':()=>{closeSheet();state.loadError=true;render();},
 'simulate-refresh-error':()=>{closeSheet();const hasContent=state.files.some(f=>f.folder===state.path.join('/'))||state.folders.some(f=>f.startsWith(state.path.length?state.path.join('/')+'/':''));if(hasContent)toast('刷新失败，已保留当前列表');else{state.loadError=true;render();}},
 'new-folder':()=>sheet('新建文件夹',`<form id="folderForm">${field('name','文件夹名称')}<button class="action-button full" type="submit">创建文件夹</button><p class="tiny-note">将在当前目录创建，演示数据仅一层生效。</p></form>`),
 'open-file':el=>{const f=state.files.find(f=>f.id===+el.dataset.id);if(['图片','视频'].includes(f.type)){state.mediaId=f.id;state.mediaError=false;navigate('media');}else sheet(f.name,`<div class="info-row"><span>类型</span><span>${f.type}</span></div><div class="info-row"><span>大小</span><span>${f.size}</span></div><p class="form-intro">此原型展示文件信息，不包含 PDF 阅读器或音频播放功能。</p>${btn('close','知道了','','action-button full')}`);},
 'file-menu':el=>{const f=state.files.find(f=>f.id===+el.dataset.id);sheet('文件操作',btn('delete-file','删除文件','trash','menu-item danger',`data-id="${el.dataset.id}"`)+`<p class="tiny-note" style="padding:10px 6px">${esc(f.name)}</p>`);},
 'delete-file':el=>confirmAction('删除文件','将从 NAS 删除此文件，此操作不可撤销。演示仅移除列表条目。','confirm-delete-file',el.dataset.id,'删除文件'),
 'confirm-delete-file':el=>{state.files=state.files.filter(f=>f.id!==+el.dataset.id);closeSheet();render();toast('演示文件已删除');},
 'task-tab':el=>{state.taskTab=el.dataset.tab;state.selectionMode=false;state.selectedTaskIds=[];render();},
 'enter-selection':()=>{state.selectionMode=true;state.selectedTaskIds=[];render();},
 'exit-selection':()=>{state.selectionMode=false;state.selectedTaskIds=[];render();},
 'select-all':()=>{const all=state.tasks.filter(t=>state.taskTab==='活跃'?['running','paused','waiting'].includes(t.status):state.taskTab==='已完成'?t.status==='completed':['failed','cancelled'].includes(t.status));state.selectedTaskIds=all.map(t=>t.id);render();},
 'toggle-select':el=>{const id=+el.dataset.id;state.selectedTaskIds=state.selectedTaskIds.includes(id)?state.selectedTaskIds.filter(x=>x!==id):[...state.selectedTaskIds,id];render();},
 'batch-delete':()=>confirmAction('批量删除',`删除所选 ${state.selectedTaskIds.length} 条任务记录？只删除记录，不会删除 NAS 上的文件。`,'confirm-batch-delete',0,'删除记录'),
 'confirm-batch-delete':()=>{const ids=new Set(state.selectedTaskIds);state.tasks=state.tasks.filter(t=>!ids.has(t.id));state.selectionMode=false;state.selectedTaskIds=[];closeSheet();render();toast('已删除所选任务记录');},
 'detail':el=>{state.taskId=+el.dataset.id;navigate('detail');},
 'pause':el=>taskStatus(el,'paused','任务已暂停'), 'resume':el=>taskStatus(el,'running','任务已恢复（模拟）'), 'retry':el=>taskStatus(el,'running','已重新开始（模拟）'),
 'cancel-task':el=>confirmAction('取消任务','停止此演示传输，已上传的远端内容不会被删除。','confirm-cancel-task',el.dataset.id,'取消任务'),
 'confirm-cancel-task':el=>{closeSheet();taskStatus(el,'cancelled','任务已取消');},
 'delete-task':el=>confirmAction('删除任务记录','只删除任务记录，不删除 NAS 文件。','confirm-delete-task',el.dataset.id,'删除记录'),
 'confirm-delete-task':el=>{state.tasks=state.tasks.filter(t=>t.id!==+el.dataset.id);closeSheet();navigate('tasks');toast('任务记录已删除');},
 'simulate-tasks-error':()=>{state.tasksLoadError=true;render();},
 'retry-tasks':()=>{state.tasksLoadError=false;render();},
 'upload':()=>uploadSheet(), 'run-preset':el=>uploadSheet(state.presets.find(p=>p.id===+el.dataset.id)),
 'pick-source':el=>{const d=state.uploadDraft;d.sourceType=el.dataset.kind;d.label=d.sourceType==='folder'?'相机 · 12 个文件 / 186 MB':'假期照片.jpg · 8.4 MB';uploadSheet();},
 'new-preset':()=>{state.editPreset=null;navigate('presetEdit');},
 'preset-menu':el=>sheet('管理预设',btn('edit-preset','编辑预设','pencil','menu-item',`data-id="${el.dataset.id}"`)+btn('delete-preset','删除预设','trash','menu-item danger',`data-id="${el.dataset.id}"`)),
 'edit-preset':el=>{state.editPreset=+el.dataset.id;closeSheet();navigate('presetEdit');},
 'delete-preset':el=>confirmAction('删除预设','不影响已创建的上传任务。','confirm-delete-preset',el.dataset.id,'删除预设'),
 'confirm-delete-preset':el=>{state.presets=state.presets.filter(p=>p.id!==+el.dataset.id);closeSheet();render();toast('预设已删除');},
 'preset-source':el=>{state.presetLocal={type:el.dataset.kind,label:''};render();},
 'pick-local':()=>{const t=state.presetLocal?.type||'folder';state.presetLocal={type:t,label:t==='folder'?'相机 · 12 个文件':'假期照片.jpg'};render();},
 'test-connection':()=>{const form=$('#connectionForm');if(!form.reportValidity())return;const url=form.elements.url.value;if(!/^https?:\/\//i.test(url)){$('#connectionResult').innerHTML='<div class="inline-message error">请使用 http:// 或 https:// 地址。</div>';return;}$('#connectionResult').innerHTML='<div class="inline-message">模拟测试通过。未向此地址发起请求。</div>';},
 'permission':el=>sheet('权限状态演示',`<p class="form-intro">原型无法修改 Android 系统权限。你可以切换演示状态，查看允许与未设置时的界面。</p>${btn('toggle-permission','切换演示状态','','action-button full',`data-kind="${el.dataset.kind}"`)}`),
 'toggle-permission':el=>{state[el.dataset.kind]=!state[el.dataset.kind];closeSheet();render();toast('已切换演示权限状态');},
 'prev-media':()=>cycleMedia(-1),'next-media':()=>cycleMedia(1),
 'simulate-media-error':()=>{state.mediaError=true;render();},
 'retry-media':()=>{state.mediaError=false;render();toast('已重新加载（模拟）');},
 'reset':()=>confirmAction('重置演示数据','所有本轮创建的连接、预设和任务都将清除，恢复到初始演示状态。','confirm-reset',0,'重置'),
 'confirm-reset':()=>{state=initial();closeSheet();render();toast('演示数据已重置');}
};
function taskStatus(el,status,message){const t=state.tasks.find(t=>t.id===+el.dataset.id);if(!t)return;t.status=status;render();toast(message);}
function cycleMedia(delta){const items=state.files.filter(f=>['图片','视频'].includes(f.type));const idx=items.findIndex(f=>f.id===state.mediaId);state.mediaId=items[(idx+delta+items.length)%items.length].id;state.mediaError=false;render();}
function toggleTheme(){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#themeToggle').innerHTML=icon(dark?'sun':'moon')+(dark?'浅色':'深色');if(state.page==='settings')render();}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){closeSheet();return;}const page=e.target.closest('[data-page]');if(page){if(page.dataset.page==='connection')state.editConnection=null;if(page.dataset.page==='presets')state.presetsSource=page.dataset.source||'home';navigate(page.dataset.page);return;}const el=e.target.closest('[data-action]');if(el){if(el.tagName==='BUTTON'&&el.closest('form')&&el.type!=='submit')e.preventDefault();actions[el.dataset.action]?.(el);}});
document.addEventListener('input',e=>{if(e.target.closest('#connectionForm,#presetForm'))state.formDirty=true;});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form));
 if(form.id==='connectionForm'){if(!/^https?:\/\//i.test(data.url)){$('#connectionResult').innerHTML='<div class="inline-message error">请输入 http:// 或 https:// WebDAV 地址。</div>';return;}if(!data.name.trim()){toast('请输入连接名称');return;}const c={id:state.editConnection||Date.now(),name:data.name.trim(),url:data.url,user:data.user,dir:data.dir,selfSigned:!!data.selfSigned};const idx=state.connections.findIndex(c=>c.id===state.editConnection);if(idx>=0)state.connections[idx]=c;else state.connections.push(c);state.formDirty=false;navigate(state.connectionSource||'home');toast('连接已保存到演示内存');}
 if(form.id==='presetForm'){const local=state.presetLocal||{type:'folder',label:''};if(!data.name.trim()){toast('请填写预设名称');return;}if(!local.label){toast('请先选择本地来源');return;}if(!data.remoteRoot.trim()){toast('请填写远端目录');return;}const p={id:state.editPreset||Date.now(),name:data.name.trim(),sourceType:local.type,source:local.label,target:data.remoteRoot,connection:data.connection,policy:data.policy,folderPolicy:local.type==='folder'?data.folderPolicy:undefined,wifiOnly:!!data.wifiOnly,deleteAfterUpload:!!data.deleteAfterUpload,chunk:data.chunk,regex:data.regex};const idx=state.presets.findIndex(p=>p.id===state.editPreset);if(idx>=0)state.presets[idx]=p;else state.presets.push(p);state.formDirty=false;navigate('presets');toast('预设已保存');}
 if(form.id==='uploadForm'){const d=state.uploadDraft;if(!d.sourceType)return;if(!data.target.trim()){toast('请填写远端目录');return;}state.tasks.unshift({id:Date.now(),name:(d.sourceType==='folder'?'文件夹上传 · ':'文件上传 · ')+d.label,status:'waiting',pct:0,total:'186 MB',done:'0 MB',count:d.sourceType==='folder'?'0 / 12':'0 / 1',target:data.target,connection:data.connection,warnings:[],policy:d.policy});if(data.savePreset){if(!data.presetName?.trim()){toast('请填写预设名称');return;}state.presets.push({id:Date.now(),name:data.presetName.trim(),sourceType:d.sourceType,source:d.label,target:data.target,connection:data.connection,policy:d.policy,folderPolicy:d.sourceType==='folder'?data.folderPolicy:undefined});}state.uploadDraft=null;closeSheet();state.taskTab='活跃';navigate('tasks');toast('演示任务已创建，不会真的上传');}
 if(form.id==='folderForm'){const n=data.name.trim();const prefix=state.path.length?state.path.join('/')+'/':'';if(!n||state.folders.includes(prefix+n)){form.elements.name.setCustomValidity('请使用非空且不重复的文件夹名称');form.reportValidity();form.elements.name.setCustomValidity('');return;}state.folders.push(prefix+n);closeSheet();render();toast('演示文件夹已创建');}
});
document.addEventListener('change',e=>{if(e.target.closest('#uploadForm')){const f=e.target.closest('#uploadForm');const d=state.uploadDraft;d.target=f.elements.target.value;d.policy=f.elements.policy.value;d.connection=f.elements.connection.value;if(f.elements.folderPolicy)d.folderPolicy=f.elements.folderPolicy.value;if(f.elements.presetName)d.presetName=f.elements.presetName.value;d.moveAfter=f.elements.moveAfter.checked;d.savePreset=f.elements.savePreset.checked;if(e.target.type==='checkbox')uploadSheet();return;}if(e.target.id==='localVideo'&&e.target.files[0]){if(videoUrl)URL.revokeObjectURL(videoUrl);videoUrl=URL.createObjectURL(e.target.files[0]);const video=document.createElement('video');video.src=videoUrl;video.controls=true;video.playsInline=true;$('.media-frame').replaceChildren(video);}});
$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const r=$('#sheet').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});
$('#themeToggle').onclick=toggleTheme;$('#resetDemo').onclick=actions.reset;
document.documentElement.dataset.theme=window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';$('#themeToggle').innerHTML=icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')+'切换主题';
render();
